import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Identify strong candidates based on mean difference and t-statistic
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            t_stat = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i], equal_var=False)[0]
            if abs(mean_diff) > 0.4 and abs(t_stat) > 3.5:
                strong_candidates.append((fid, abs(mean_diff), abs(t_stat)))

    # Sort by t-statistic descending
    strong_candidates.sort(key=lambda x: x[2], reverse=True)

    # Remove near-duplicates (correlated features)
    selected_fid_set = set()
    drivers = []
    for fid, _, _ in strong_candidates:
        is_duplicate = False
        for selected_fid in selected_fid_set:
            col_a = feats.column(selected_fid)
            col_b = feats.column(fid)
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]) > 0.6:
                is_duplicate = True
                break
        if not is_duplicate:
            selected_fid_set.add(fid)
            drivers.append(fid)
            if len(drivers) >= MAX_DRIVERS:
                break

    # If no clear drivers, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select all features with strong correlations to drivers
    columns = set()
    for fid in drivers:
        columns.add(fid)
        col_idx = feats.column(fid)
        # Add correlated features
        for other_fid in feats.ids:
            if other_fid == fid:
                continue
            other_col_idx = feats.column(other_fid)
            corr = np.corrcoef(feats.x[:, col_idx], feats.x[:, other_col_idx])[0,1]
            if abs(corr) > 0.6:
                columns.add(other_fid)

    # Create products of pairs among selected features
    products = []
    columns_list = list(columns)
    for i in range(len(columns_list)):
        for j in range(i+1, len(columns_list)):
            products.append((columns_list[i], columns_list[j]))

    # Weighted score using mean difference as weights
    loadings = {}
    for fid in columns_list:
        col_idx = feats.column(fid)
        diff = np.mean(feats.x[feats.y==1, col_idx]) - np.mean(feats.x[feats.y==0, col_idx])
        loadings[fid] = abs(diff)

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns_list),
        products=tuple(products),
        loadings=loadings
    )
